import{z as E,x as A,o as t,c as B,q as d,j as l,D as r,d as e,s as i,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"CIDR 与聚合","description":"","frontmatter":{"title":"CIDR 与聚合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cidr-agg.md","filePath":"cs/cidr-agg.md","lastUpdated":1791413859000}'),c={name:"cs/cidr-agg.md"};function p(D,a,m,C,u,h){const s=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=d('<h1 id="cidr-与聚合" tabindex="-1">CIDR 与聚合 <a class="header-anchor" href="#cidr-与聚合" aria-label="Permalink to &quot;CIDR 与聚合&quot;">​</a></h1><div class="epigraph"><p>前缀长度不再被三类地址锁死；相邻的一块可以在表里收成更短的一条，只要出口相同。</p><footer>—— 据 Fuller 等 CIDR；RFC 791 的地址仍是 32 位，分类被放弃</footer></div><p><a href="/cs/ip-subnet">上一课</a>给出 IPv4 地址与掩码：同一子网直连，跨网走路由器。本课不重算「主机位有几位」。缺口是分类编址把掩码钉成 /8、/16、/24，表项随机构爆炸，且不能把多块连续空间写成一条。CIDR：任意前缀长度，<strong>聚合</strong>把一簇更长前缀收成更短前缀。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RFC 791 的地址是 32 位；早期按首比特分成 A/B/C 类，路由器按类猜掩码。B 类太大、C 类太碎，核心表涨得比线路快。无类别域间路由让每条路由自带前缀长：<code>10.1.0.0/16</code> 覆盖其中所有 /24，若它们下一跳相同，只需一条。<span class="marginnote">术语翻译：<code>/16</code> 读作「前 16 位是网络号、后 16 位留给主机」；CIDR 的意思就是这个「/几」可以停在任意一位——不必像分类时代那样只能是 8、16、24 的整数档。掩码变成了一根可以任意位置切分的尺子。</span>缺口是<strong>表的收缩规则</strong>，不是最长匹配怎么查——那是下一课。</p><p><span class="marginnote">聚合的前提是覆盖完整且策略相同。有一个 /24 要走另一出口，就必须把它作为更具体的例外留下，这正是后课 LPM 的输入。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路由通告带前缀与长度。聚合：若一组前缀构成某更短前缀的完全划分（或运维接受把空洞也收入），且出口一致，则只保留短前缀。主机接口仍用「地址 + 前缀长」判断直连，与分类无关。私网块（如 <code>10.0.0.0/8</code>）同样是 CIDR 前缀，后课 NAT 会用到。</p>',8)),(t(),l(n,null,{default:r(()=>[i(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLASS%5B%22A%2FB%2FC%20%E5%9B%BA%E5%AE%9A%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20EXP%5B%22%E8%A1%A8%E9%A1%B9%E8%86%A8%E8%83%80%22%5D%0A%20%20CIDR%5B%22%E4%BB%BB%E6%84%8F%E5%89%8D%E7%BC%80%E9%95%BF%22%5D%20--%3E%20AGG%5B%22%E7%9B%B8%E5%90%8C%E5%87%BA%E5%8F%A3%E5%88%99%E8%81%9A%E5%90%88%22%5D%0A%20%20AGG%20--%3E%20TAB%5B%22%E6%9B%B4%E7%9F%AD%E7%9A%84%E4%B8%80%E5%BC%A0%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("CIDR 把「网络号」从类别改成（前缀，长度）对，使 "),o("a",{href:"/cs/arp"},"ARP"),e(" 的「是否同一链路」与核心转发表用同一种语言。聚合减少控制平面与 FIB 容量；数据平面转发仍是查表。端到端不变：前缀是定位与可达，不是文件完整性。")],-1)),a[5]||(a[5]=o("p",null,"四块连续且出口一致的 /24 收成一条 /22：",-1)),(t(),l(n,null,{default:r(()=>[i(s,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%2210.0.4.0%2F24%22%5D%20--%3E%20AGG%5B%22%E5%9B%9B%E5%9D%97%E8%BF%9E%E7%BB%AD%E4%B8%94%E4%B8%8B%E4%B8%80%E8%B7%B3%E4%B8%80%E8%87%B4%22%5D%0A%20%20P2%5B%2210.0.5.0%2F24%22%5D%20--%3E%20AGG%0A%20%20P3%5B%2210.0.6.0%2F24%22%5D%20--%3E%20AGG%0A%20%20P4%5B%2210.0.7.0%2F24%22%5D%20--%3E%20AGG%0A%20%20AGG%20--%3E%20ONE%5B%22%E5%AF%B9%E5%A4%96%E5%8F%AA%E9%80%9A%E5%91%8A%E4%B8%80%E6%9D%A1%2010.0.4.0%2F22%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=d('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 BGP 如何宣布聚合、何时带 ATOMIC_AGGREGATE 写完。也不引入 IPv6 的 /48 分配政策。查找冲突（长短前缀同时命中）下一课最长前缀匹配。<span class="marginnote">常见误区：聚合块必须「对齐」——不能随手把 <code>10.0.3.0/24</code> 与 <code>10.0.4.0/24</code> 收成一条 /23。/23 的边界只会落在第三个八位组为偶数的地方（如 <code>10.0.2.0/23</code>、<code>10.0.4.0/23</code>），<code>10.0.3.x</code> 横跨在这两个 /23 的缝上，硬收会把不属于你的 <code>10.0.2.x</code> 也吞进去。</span></p><p>后课默认：表项是前缀，可以嵌套。嵌套时选哪一条，下一课 LPM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CIDR 让掩码任意；聚合用短前缀代替一簇长前缀。<span class="marginnote">数字实例：/24 有 \\(2^8=256\\) 个地址，/22 有 \\(2^{10}=1024\\) 个地址，恰好等于 4 个 /24；前缀长度每缩短 1 位，块的大小就翻一倍。所以「收短一位」对应「把相邻对收成一块」，四块连续的 /24 恰好收成 /22。</span></li><li>分类编址不再是转发规则。</li><li>多条命中时如何选，下一课。</li><li>出处：CIDR（Fuller 等）；RFC 791；Kurose and Ross。</li></ul>',5))])}const P=E(c,[["render",p]]);export{f as __pageData,P as default};
